#include "accessor_shim.h"
#include "source_kernels.inc"
#include "study_cases.h"
#include <vector>
#include <fstream>
#include <string>
#include <memory>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <algorithm>
#include <limits>
static void ck(cudaError_t s){if(s!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(s));exit(3);}}
template<typename T>static std::vector<T>load(std::string f,size_t n){std::ifstream s(f,std::ios::binary);std::vector<T>x(n);s.read((char*)x.data(),n*sizeof(T));if(!s||s.peek()!=EOF)throw std::runtime_error("fixturebytes "+f);return x;}
template<typename T>static std::vector<T>host(T*p,int n){std::vector<T>x(n);ck(cudaMemcpy(x.data(),p,n*sizeof(T),cudaMemcpyDeviceToHost));return x;}
template<typename T>static void cat(std::vector<double>&a,const std::vector<T>&b){for(auto v:b)a.push_back(double(v));}
__global__ void observe_params(int b,int m,int n,int k,int r,int*p){p[0]=b;p[1]=m;p[2]=n;p[3]=k;p[4]=r;}
struct Base{Case c;virtual void warm()=0;virtual double trial(std::vector<double>&,std::vector<double>&)=0;virtual~Base()=default;};
template<typename T>struct Work:Base{T *a,*b,*go,*out,*sd,*ss,*g1,*g2;int*params;Work(Case x){c=x;auto A=load<T>("case"+std::to_string(c.id)+"_x1.bin",c.na+16),B=load<T>("case"+std::to_string(c.id)+"_x2.bin",c.nb+16),G=load<T>("case"+std::to_string(c.id)+"_go.bin",c.nq+16);ck(cudaMalloc(&a,A.size()*sizeof(T)));ck(cudaMalloc(&b,B.size()*sizeof(T)));ck(cudaMalloc(&go,G.size()*sizeof(T)));ck(cudaMemcpy(a,A.data(),A.size()*sizeof(T),cudaMemcpyHostToDevice));ck(cudaMemcpy(b,B.data(),B.size()*sizeof(T),cudaMemcpyHostToDevice));ck(cudaMemcpy(go,G.data(),G.size()*sizeof(T),cudaMemcpyHostToDevice));ck(cudaMalloc(&params,20));for(auto p:{&out,&sd,&ss})ck(cudaMalloc(p,(c.nq+16)*sizeof(T)));ck(cudaMalloc(&g1,(c.na+16)*sizeof(T)));ck(cudaMalloc(&g2,(c.nb+16)*sizeof(T)));reset();}
void reset(){for(auto p:{out,sd,ss}){std::vector<T>x(c.nq+16,T(91.25));std::fill(x.begin()+8,x.end()-8,std::numeric_limits<T>::quiet_NaN());ck(cudaMemcpy(p,x.data(),x.size()*sizeof(T),cudaMemcpyHostToDevice));}for(auto p:{std::make_pair(g1,c.na),std::make_pair(g2,c.nb)}){std::vector<T>x(p.second+16,T(91.25));std::fill(x.begin()+8,x.end()-8,std::numeric_limits<T>::quiet_NaN());ck(cudaMemcpy(p.first,x.data(),x.size()*sizeof(T),cudaMemcpyHostToDevice));}}
void forward(){_braycurtis_forward_kernel_impl<T,int><<<(c.nq+255)/256,256>>>(c.nq,acc(a+8,c.b,c.m,c.k),acc(b+8,c.b,c.n,c.k),acc(out+8,c.b,c.m,c.n));}
void backward(){_braycurtis_forward_components_kernel_impl<T,int><<<(c.nq+255)/256,256>>>(c.nq,acc(a+8,c.b,c.m,c.k),acc(b+8,c.b,c.n,c.k),acc(sd+8,c.b,c.m,c.n),acc(ss+8,c.b,c.m,c.n));_braycurtis_backward_x1_kernel_impl<T,int><<<(c.na+255)/256,256>>>(c.na,acc(go+8,c.b,c.m,c.n),acc(sd+8,c.b,c.m,c.n),acc(ss+8,c.b,c.m,c.n),acc(a+8,c.b,c.m,c.k),acc(b+8,c.b,c.n,c.k),acc(g1+8,c.b,c.m,c.k));_braycurtis_backward_x2_kernel_impl<T,int><<<(c.nb+255)/256,256>>>(c.nb,acc(go+8,c.b,c.m,c.n),acc(sd+8,c.b,c.m,c.n),acc(ss+8,c.b,c.m,c.n),acc(a+8,c.b,c.m,c.k),acc(b+8,c.b,c.n,c.k),acc(g2+8,c.b,c.n,c.k));}
void warm(){for(int i=0;i<c.repeats;i++)forward();ck(cudaDeviceSynchronize());for(int i=0;i<c.repeats;i++)backward();ck(cudaDeviceSynchronize());}
double trial(std::vector<double>&pre,std::vector<double>&outputs){reset();auto A=host(a,c.na+16),B=host(b,c.nb+16),G=host(go,c.nq+16);observe_params<<<1,1>>>(c.b,c.m,c.n,c.k,c.repeats,params);ck(cudaDeviceSynchronize());auto echo=host(params,5);auto t=std::chrono::steady_clock::now();for(int i=0;i<c.repeats;i++)forward();ck(cudaDeviceSynchronize());double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/c.repeats;t=std::chrono::steady_clock::now();for(int i=0;i<c.repeats;i++)backward();ck(cudaDeviceSynchronize());sec+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()/c.repeats;cat(pre,std::vector<int>{c.type,c.b,c.m,c.n,c.k,c.repeats});cat(pre,echo);cat(pre,A);cat(pre,B);cat(pre,G);cat(pre,host(a,c.na+16));cat(pre,host(b,c.nb+16));cat(pre,host(go,c.nq+16));for(auto p:{out,sd,ss})cat(outputs,host(p,c.nq+16));cat(outputs,host(g1,c.na+16));cat(outputs,host(g2,c.nb+16));return sec;}
~Work(){for(auto p:{a,b,go,out,sd,ss,g1,g2})ck(cudaFree(p));ck(cudaFree(params));}};
int main(){std::vector<std::unique_ptr<Base>>w;for(auto c:cases){if(c.type==32)w.emplace_back(new Work<float>(c));else w.emplace_back(new Work<double>(c));}auto expected=load<double>("oracle_f64.bin",COUNT),at=load<double>("oracle_atol_f64.bin",COUNT),rt=load<double>("oracle_rtol_f64.bin",COUNT);for(auto&x:w)x->warm();for(int trial=1;trial<=5;trial++){std::vector<double>pre,out;double secs=0;for(auto&x:w)secs+=x->trial(pre,out);pre.insert(pre.end(),out.begin(),out.end());if(pre.size()!=COUNT)throw std::runtime_error("artifactcount");bool ok=true;double ma=0,mr=0;for(int i=0;i<COUNT;i++){double d=fabs(pre[i]-expected[i]);ok&=std::isfinite(pre[i])&&d<=at[i]+rt[i]*fabs(expected[i]);ma=std::max(ma,d);mr=std::max(mr,d/std::max(fabs(expected[i]),1e-300));}std::string path=std::string(getenv("STUDY_OUTPUT_DIR"))+"/bray_native_trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)pre.data(),pre.size()*8);f.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":%.17g,\"jit_excluded\":true,\"timing_region\":\"sum6_source_forward_plus3kernel_backward_means_R10\",\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,secs,ok?"true":"false",pre.size(),ma,mr,path.c_str(),pre.size());fflush(stdout);if(!ok)return 4;}return 0;}
